void *gl_get_function_pointer(const char *name) {
    for (int i = 0; gl_func_table[i].name != nullptr; ++i) {
        if (__builtin_strcmp(name, gl_func_table[i].name) == 0)
            return gl_func_table[i].ptr;
    }
    return nullptr;
}
